{"content": "def merge_tool_results(calls, results):
    """Merge tool call results into a per-call dict.

    Returns a list of dicts, one per call in call order:
        {'id': id, 'status': 'done', 'content': content}  if a result exists
        {'id': id, 'status': 'pending'}                  otherwise

    The last result for an id wins. Unknown ids are ignored. Duplicate call ids raise ValueError.
    Neither input is mutated.
    """
    if not isinstance(calls, list) or not isinstance(results, list):
        raise ValueError("calls and results must be lists")

    # Build a mapping from call id -> list of results (preserving order).
    result_map = {}
    for r in results:
        if not isinstance(r, dict):
            raise ValueError("each result must be a dict")
        rid = r.get("id")
        if rid is None:
            raise ValueError("each result must have an 'id'")
        result_map.setdefault(rid, []).append(r)

    # Validate call ids: no duplicates.
    seen = set()
    for c in calls:
        if not isinstance(c, dict):
            raise ValueError("each call must be a dict")
        cid = c.get("id")
        if cid is None:
            raise ValueError("each call must have an 'id'")
        if cid in seen:
            raise ValueError(f"duplicate call id: {cid}")
        seen.add(cid)

    # Build output in call order.
    out = []
    for c in calls:
        cid = c.get("id")
        if cid is None:
            raise ValueError("call missing 'id'")
        calls_for_id = result_map.get(cid, [])
        if calls_for_id:
            # Last result wins.
            last = calls_for_id[-1]
            content = last.get("content", "")
            out.append({"id": cid, "status": "done", "content": content})
        else:
            out.append({"id": cid, "status": "pending"})
    return out
